using System.Text;
using System.Text.RegularExpressions;

namespace Locara.Core;

public sealed record XUnityExportResult(
    string OutputDirectory,
    string TranslationFile,
    string ConfigFile,
    int ExportedCount,
    bool ShapedArabic,
    string FontFileName);

/// <summary>
/// Format handler for XUnity.AutoTranslator (BepInEx) key=value .txt files
/// (e.g. BepInEx/Translation/*/Text/_AutoGeneratedTranslations.txt).
/// Enables scanning captured strings from hardcoded Unity games, translating them in Locara,
/// and writing back cleanly escaped key=value lines.
/// </summary>
public sealed partial class XUnityTranslationFormat : IFormatHandler
{
    public static XUnityTranslationFormat Instance { get; } = new();
    public string Name => "xunity-autotranslator";

    public bool Supports(string path)
    {
        if (!Path.GetExtension(path).Equals(".txt", StringComparison.OrdinalIgnoreCase))
            return false;
        string normalized = path.Replace('\\', '/');
        string file = Path.GetFileName(normalized);
        if (file.Equals("_AutoGeneratedTranslations.txt", StringComparison.OrdinalIgnoreCase)
            || file.Equals("_LocaraTranslations.txt", StringComparison.OrdinalIgnoreCase)
            || file.Equals("_Substitutions.txt", StringComparison.OrdinalIgnoreCase))
            return true;
        return XUnityFolderPattern().IsMatch(normalized);
    }

    public IReadOnlyList<TextSlot> Extract(byte[] bytes)
    {
        string text = DecodeUtf8(bytes);
        var slots = new List<TextSlot>();
        string[] lines = SplitLines(text, out _);
        for (int i = 0; i < lines.Length; i++)
        {
            if (!TrySplitKeyValue(lines[i], out string rawKey, out string rawVal))
                continue;
            if (rawKey.StartsWith("r:", StringComparison.Ordinal)
                || rawKey.StartsWith("sr:", StringComparison.Ordinal))
                continue;

            string key = Unescape(rawKey);
            string val = Unescape(rawVal);
            if (string.IsNullOrWhiteSpace(key)) continue;

            string existing = string.IsNullOrEmpty(val) || val == key ? "" : val;
            slots.Add(new TextSlot($"line:{i}", key, $"XUnity.AutoTranslator · السطر {i + 1}", existing));
        }
        return slots;
    }

    public byte[] Apply(byte[] bytes, IReadOnlyDictionary<string, string> translations)
    {
        if (translations.Count == 0) return bytes;
        string text = DecodeUtf8(bytes);
        string[] lines = SplitLines(text, out string eol);
        bool changed = false;

        for (int i = 0; i < lines.Length; i++)
        {
            if (!translations.TryGetValue($"line:{i}", out string? translated)) continue;
            if (!TrySplitKeyValue(lines[i], out string rawKey, out _)) continue;
            string updatedLine = $"{rawKey}={Escape(translated)}";
            if (updatedLine != lines[i])
            {
                lines[i] = updatedLine;
                changed = true;
            }
        }

        if (!changed) return bytes;
        bool hadBom = bytes.Length >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF;
        string rebuilt = string.Join(eol, lines);
        byte[] utf8 = Encoding.UTF8.GetBytes(rebuilt);
        if (!hadBom) return utf8;
        byte[] withBom = new byte[utf8.Length + 3];
        withBom[0] = 0xEF; withBom[1] = 0xBB; withBom[2] = 0xBF;
        Buffer.BlockCopy(utf8, 0, withBom, 3, utf8.Length);
        return withBom;
    }

    internal static string Escape(string text)
    {
        var sb = new StringBuilder(text.Length + 8);
        foreach (char c in text)
        {
            switch (c)
            {
                case '\\': sb.Append("\\\\"); break;
                case '=': sb.Append("\\="); break;
                case '\r': sb.Append("\\r"); break;
                case '\n': sb.Append("\\n"); break;
                default: sb.Append(c); break;
            }
        }
        return sb.ToString();
    }

    internal static string Unescape(string text)
    {
        if (!text.Contains('\\')) return text;
        var sb = new StringBuilder(text.Length);
        for (int i = 0; i < text.Length; i++)
        {
            char c = text[i];
            if (c == '\\' && i + 1 < text.Length)
            {
                char next = text[++i];
                sb.Append(next switch
                {
                    'n' => '\n',
                    'r' => '\r',
                    't' => '\t',
                    '=' => '=',
                    '\\' => '\\',
                    _ => next
                });
            }
            else
            {
                sb.Append(c);
            }
        }
        return sb.ToString();
    }

    internal static bool TrySplitKeyValue(string line, out string rawKey, out string rawValue)
    {
        rawKey = "";
        rawValue = "";
        if (string.IsNullOrWhiteSpace(line)) return false;
        string trimmed = line.TrimStart();
        if (trimmed.StartsWith("//", StringComparison.Ordinal) || trimmed.StartsWith('#'))
            return false;

        int eq = -1;
        for (int i = 0; i < line.Length; i++)
        {
            if (line[i] == '\\')
            {
                i++; // skip escaped character
                continue;
            }
            if (line[i] == '=')
            {
                eq = i;
                break;
            }
        }
        if (eq <= 0) return false;
        rawKey = line[..eq];
        rawValue = line[(eq + 1)..];
        return true;
    }

    private static string DecodeUtf8(byte[] bytes)
    {
        if (bytes.Length >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF)
            return Encoding.UTF8.GetString(bytes, 3, bytes.Length - 3);
        return Encoding.UTF8.GetString(bytes);
    }

    private static string[] SplitLines(string text, out string eol)
    {
        eol = text.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";
        return text.Replace("\r\n", "\n").Split('\n');
    }

    [GeneratedRegex(@"(?:^|/)(?:BepInEx|AutoTranslator)/Translation/[^/]+/Text/[^/]+\.txt$", RegexOptions.IgnoreCase)]
    private static partial Regex XUnityFolderPattern();
}

/// <summary>
/// Exports translated units into a ready-to-drop BepInEx / XUnity.AutoTranslator overlay
/// for Unity games whose strings are hardcoded in C#/IL2CPP or stripped MonoBehaviours.
/// </summary>
public static class XUnityAutoTranslatorExporter
{
    public static XUnityExportResult Export(
        string destinationDirectory,
        IEnumerable<Unit> units,
        ArabicFontChoice fontChoice,
        UnityArabicDisplayOptions displayOptions,
        bool finalOnly,
        string engineName = "unity")
    {
        string dest = Path.GetFullPath(destinationDirectory);
        string textDir = Path.Combine(dest, "BepInEx", "Translation", "ar", "Text");
        string configDir = Path.Combine(dest, "BepInEx", "config");
        string fontDir = Path.Combine(dest, "BepInEx", "Translation", "ar", "Fonts");
        Directory.CreateDirectory(textDir);
        Directory.CreateDirectory(configDir);
        Directory.CreateDirectory(fontDir);

        var seenSources = new HashSet<string>(StringComparer.Ordinal);
        var lines = new List<string>
        {
            "// Exported by Locara for XUnity.AutoTranslator (BepInEx)",
            $"// Mode: {(finalOnly ? "Approved only" : "Approved + Translated")} | Arabic Shaping: {(displayOptions.ShapeArabic ? "ON (Visual RTL)" : "OFF (Logical UTF-8)")}"
        };

        int exported = 0;
        foreach (var unit in units)
        {
            if (string.IsNullOrWhiteSpace(unit.Source) || string.IsNullOrWhiteSpace(unit.Target))
                continue;
            if (finalOnly && unit.Status != "approved")
                continue;
            if (!finalOnly && unit.Status is not ("approved" or "translated"))
                continue;
            if (unit.Warning.Length != 0 || Tokens.Validate(unit.Source, unit.Target, engineName).Length != 0)
                continue;
            if (!seenSources.Add(unit.Source))
                continue;

            string effectiveTarget = displayOptions.ShapeArabic
                ? displayOptions.TransformArabic(unit.Target)
                : unit.Target;
            lines.Add($"{XUnityTranslationFormat.Escape(unit.Source)}={XUnityTranslationFormat.Escape(effectiveTarget)}");
            exported++;
        }

        string translationFile = Path.Combine(textDir, "_LocaraTranslations.txt");
        File.WriteAllText(translationFile, string.Join("\r\n", lines) + "\r\n", new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));

        string safeFontName = string.IsNullOrWhiteSpace(fontChoice.FontFamilyName)
            ? "LocaraArabic.ttf"
            : Regex.Replace(fontChoice.FontFamilyName, @"[^A-Za-z0-9._-]+", "") + ".ttf";
        string fontPath = Path.Combine(fontDir, safeFontName);
        byte[] fontBytes = ArabicFontCatalog.LoadBytes(fontChoice);
        File.WriteAllBytes(fontPath, fontBytes);
        ArabicFontCatalog.WriteLicense(fontDir, fontChoice);

        string configFile = Path.Combine(configDir, "AutoTranslatorConfig.ini");
        string configContent = """
            ; Generated by Locara — Drop the BepInEx folder into your Unity game root
            ; Requires BepInEx + XUnity.AutoTranslator-BepInEx installed in the game directory.

            [Service]
            Endpoint=
            FallbackEndpoint=

            [General]
            Language=ar
            FromLanguage=en

            [Files]
            Directory=Translation\{Lang}\Text
            OutputFile=Translation\{Lang}\Text\_AutoGeneratedTranslations.txt

            [TextFrameworks]
            EnableUGUI=True
            EnableNGUI=True
            EnableTextMeshPro=True
            EnableTextMesh=True
            EnableIMGUI=True

            [Behaviour]
            MaxCharactersPerTranslation=1000
            IgnoreWhitespaceInDialogue=False
            IgnoreWhitespaceInNGUI=False
            MinDialogueChars=20
            ForceSplitTextAfterCharacters=0
            CopyToClipboard=False
            EnableBatching=False
            EnableUIResizing=True
            OverrideFont=
            OverrideFontTextMeshPro=
            FallbackFontTextMeshPro=
            """;
        File.WriteAllText(configFile, configContent.Replace("\r\n", "\n").Replace("\n", "\r\n") + "\r\n", new UTF8Encoding(false));

        string readmeFile = Path.Combine(dest, "README_XUnity_Arabic.txt");
        string readme = $"""
            حزمة تصدير XUnity.AutoTranslator (BepInEx) — مُولّدة بواسطة Locara
            ==================================================================
            عدد النصوص المُصدّرة: {exported}
            وضع تشكيل العربية: {(displayOptions.ShapeArabic ? "مُفعّل (تشكيل مسبق لـ TextMeshPro)" : "مُعطّل (عربي منطقي RTL أصلي)")}
            الخط العربي المرفق: BepInEx/Translation/ar/Fonts/{safeFontName} ({fontChoice.DisplayName})

            خطوات الاستخدام للألعاب التي تخزّن نصوصها داخل الكود البرمجي (Hardcoded Unity):
            1. ثبّت BepInEx وإضافة XUnity.AutoTranslator-BepInEx في مجلد اللعبة.
            2. انسخ مجلد BepInEx من هذا المجلد إلى مجلد اللعبة الرئيسي ووافق على الدمج.
            3. إذا كانت اللعبة تستخدم TextMeshPro بدون خط عربي مدمج، ضع اسم AssetBundle للخط العربي
               في خيار FallbackFontTextMeshPro داخل BepInEx/config/AutoTranslatorConfig.ini.
            4. لتعريب النصوص الجديدة التي يلتقطها XUnity أثناء اللعب: افتح ملف
               BepInEx/Translation/ar/Text/_AutoGeneratedTranslations.txt داخل Locara وترجمه مباشرة!
            """;
        File.WriteAllText(readmeFile, readme, new UTF8Encoding(false));

        return new XUnityExportResult(dest, translationFile, configFile, exported, displayOptions.ShapeArabic, safeFontName);
    }
}
